        intro1: 'Wer zuerst vier Steine der eigenen Farbe in eine Linie bringt – waagerecht, senkrecht oder entlang einer der beiden Diagonalen –, holt die Runde. Sind alle 42 Felder ohne Linie belegt, endet die Runde unentschieden.',
