        data: 'Benutzername, E-Mail-Adresse, dein Passwort (nur als bcrypt-Einweg-Hash gespeichert), Profilbild, Bio, Akzentfarbe und Einstellungen, die von dir verknüpften Anmeldeanbieter, der Zeitpunkt deines letzten Zurücksetzens des Passworts oder deiner letzten E-Mail-Änderung (nur verwendet, um ältere Sitzungen abzumelden), die Website oder Kampagne, über die du bei der Registrierung gekommen bist, und wann du die Nutzungsbedingungen akzeptiert und bestätigt hast, dass du 13 Jahre oder älter bist.',
        basis: 'Vertrag: Dein Konto beruht auf den Nutzungsbedingungen, die du beim Erstellen akzeptierst, nicht auf einer Einwilligung, und wir brauchen diese Daten, um es zu führen. Die Herkunft der Registrierung: unser berechtigtes Interesse zu wissen, über welche Kanäle neue Spieler kommen.',
        retention: 'Bis du das Konto löschst. Ab {{inactiveFrom}} löschen wir außerdem ein Konto, das {{inactiveMonths}} Monate lang nicht genutzt wurde: Wir schreiben dir {{inactiveWarningDays}} Tage vorher eine E-Mail, und eine einzige Anmeldung erhält das Konto. Ein Konto, das Premium hat oder hatte, jemals einen Premium-Kauf begonnen hat oder gesperrt ist, wird aus diesem Grund nicht gelöscht. Wenn du dich mit E-Mail-Adresse und Passwort registrierst und die Adresse nie bestätigst, wird das Konto nach {{unverifiedDays}} Tagen gelöscht, es sei denn, du hast Google, GitHub oder Discord damit verknüpft oder es hat Premium oder hat jemals einen Premium-Kauf begonnen.',
        extra: 'Dein Benutzername, dein Bild und deine Ergebnisse in der Bestenliste sind für alle sichtbar, unabhängig von deinen Einstellungen: Die öffentliche Bestenliste zeigt sie für jedes Konto mit genügend beendeten Spielen, und deine Profilseite zeigt immer deinen Benutzernamen und dein Bild, mit einem Hinweis, dass das Profil privat ist, wenn es das ist. Der Rest deines Profils (Bio, Spielstatistiken, Erfolge, Premium-Status und Online-Status, den du auch einzeln ausschalten kannst) folgt seiner Sichtbarkeitseinstellung: Alle können ihn sehen, wenn das Profil öffentlich ist, nur deine Freunde, wenn es auf Freunde beschränkt ist, und niemand außer dir, wenn es privat ist. In gemeinsamen Lobbys und Spielen sehen die anderen Spieler außerdem dein Premium-Abzeichen und die Spielergebnisse, auch auf deiner Spielerkarte dort, unabhängig von der Einstellung. Ein neues Konto startet auf Freunde beschränkt und mit ausgeblendetem Online-Status. Bei deiner ersten Anmeldung bieten wir dir an, das Profil öffentlich zu machen, und du kannst beides jederzeit in deinen Profileinstellungen ändern. Konten, die vor dieser Änderung erstellt wurden, behalten ihre bisherigen Einstellungen: ein öffentliches Profil und angezeigten Online-Status, sofern nicht geändert.',
