        data: 'Deine E-Mail-Adresse und die Nachricht: Bestätigungslinks und Links zum Zurücksetzen des Passworts, Sicherheitshinweise, Spieleinladungen von Freunden, die Benachrichtigungen, die du auswählst, Kaufbestätigungen, Hinweise auf Änderungen unserer Nutzungsbedingungen, eine Warnung, bevor ein ungenutztes Konto gelöscht wird, und, solange ein Premium-Abonnement läuft, mindestens alle sechs Monate eine Erinnerung, dass es läuft und wie du es beendest. Wenn jemand die E-Mail-Adresse eines Kontos ändern möchte, senden wir einen Sicherheitshinweis an die alte Adresse, in dem die neue teilweise verborgen ist. Um Fluten von Bestätigungs- und Zurücksetzungs-E-Mails zu verhindern, speichern wir einen gekürzten Einweg-Hash der Adresse für 10 Minuten und einen Tageszähler für 26 Stunden.',
