        title: 'Premium',
        data: 'Premium wird über Link verkauft: Das mit Stripe verbundene Unternehmen Sold through Link, LLC (USA) ist der Händler (Merchant of Record) und nimmt die Zahlung entgegen. Zur Berechnung der Mehrwertsteuer oder Verkaufssteuer (Sales Tax) erhebt Link beim Bezahlvorgang deinen Namen, deine Rechnungsadresse und gegebenenfalls deine Steuer-ID und teilt die Bestellinformationen mit uns: deine Kontaktdaten, Rechnungsadresse, Zahlungsinformationen, Steuer-ID und die Bestelldetails. Außerdem aktualisiert Link den Namen und die Rechnungsadresse in deinem Kundendatensatz in unserem Stripe-Konto. Deine vollständige Kartennummer erhalten wir nie. Wir speichern deine Stripe-Kunden- und Abonnement-IDs, deinen Premium-Status und die zugehörigen Zeitpunkte sowie einen Nachweis dessen, was du beim Bezahlvorgang akzeptiert hast: den Tarif, die Versionen der Bedingungen und der Widerrufsinformationen, die dir angezeigt wurden, und wann du zugestimmt hast.',
        basis: 'Vertrag. Der Nachweis zum Bezahlvorgang: außerdem unser berechtigtes Interesse, belegen zu können, was du akzeptiert hast.',
        retention: 'Bis du das Konto löschst. Dann kündigen wir ein laufendes Abonnement und löschen deinen Kundendatensatz bei Stripe. Stripe und Link bewahren ihre eigenen Zahlungs- und Bestelldaten auf, wie in ihren Datenschutzerklärungen beschrieben. Wenn du dein Link-Konto löschst, wird ein über Link verkauftes Abonnement gekündigt, und die Angaben, die du für diese Bestellung gemacht hast, werden gelöscht.',
