    storage: {
      title: '6. Cookies und Speicherung auf deinem Gerät',
      lead: 'Wir speichern nur, was die Website zum Funktionieren braucht, plus die hier aufgeführten Einträge:',
      session: 'Ein Anmelde-Cookie, das dich angemeldet hält, und, solange du angemeldet bist, eine Kopie der Liste der von dir blockierten Spieler, damit der Chat sie schon vor dem Laden der Liste ausblendet. Beim Abmelden wird die Kopie entfernt.',
      guest: 'Für Gäste: die Gast-ID, der Name und das Identitätstoken, die dich mit deinen Spielen verbunden halten, sowie die Liste der von dir blockierten Spieler. Das Token gilt {{guestTokenDays}} Tage ab deinem letzten Besuch, und „Vergiss mich“ entfernt alles davon.',
      preferences: 'Deine Sprache, dein Design, Ton und ähnliche Einstellungen sowie welche Hinweise du geschlossen hast.',
      lastAccount: 'Nur wenn du bei der Anmeldung mit E-Mail-Adresse und Passwort „Angemeldet bleiben“ ankreuzt: diese Adresse, damit die Anmeldeseite sie beim nächsten Mal vorschlagen kann. Sie bleibt nach dem Abmelden auf dem Gerät; eine Anmeldung ohne Häkchen bei „Angemeldet bleiben“ oder das Löschen der Daten dieser Website in deinem Browser entfernt sie.',
      google: 'Das in Abschnitt 5 beschriebene Einwilligungs-Cookie von Google.',
      serviceWorker: 'Unser Service Worker, der Push-Benachrichtigungen empfängt und eine Kopie der eigenen Dateien der Website vorhält, damit Seiten schneller laden.',
      noTrackers: 'Wir setzen keine eigenen Werbe- oder Analyse-Kennungen. Die Website oder Kampagne, über die du gekommen bist, wird mit der Anfrage übertragen, die dein Konto erstellt, und nie in deinem Browser gespeichert.',
    },
    rights: {
      title: '7. Deine Rechte',
      lead: 'Du hast das Recht auf Auskunft über deine Daten, auf ihre Berichtigung oder Löschung, auf Einschränkung ihrer Verarbeitung, darauf, sie in einem maschinenlesbaren Format zu erhalten, und auf Widerspruch gegen eine Verarbeitung, die auf unserem berechtigten Interesse beruht. Wo wir uns auf eine Einwilligung stützen, kannst du sie jederzeit widerrufen; das berührt nicht, was wir davor getan haben.',
      export: 'Deine Daten herunterladen: Die Schaltfläche „Meine Daten herunterladen“ im Bereich „Deine Daten“ auf deiner Profilseite gibt dir eine JSON-Datei mit deinem Profil, deinen Einstellungen, verknüpften Anbietern, Spielen, von dir erstellten Lobbys, Käufen und Nachweisen zum Bezahlvorgang, Freunden, Freundschaftsanfragen, von dir blockierten Spielern, Einladungen, Benachrichtigungen, Feedback, von dir eingereichten Meldungen, Erfolgen und Push-Abonnements.',
      correct: 'Deine Daten berichtigen: Bearbeite dein Profil, einschließlich deiner E-Mail-Adresse, auf deiner Profilseite.',
      delete: 'Lösche dein Konto auf deiner Profilseite, im Browser oder in der Android-App: Wähle unter „Gefahrenzone“ die Option „Konto löschen“ und bestätige über den Link, den wir dir per E-Mail schicken. Dabei entfernen wir auch dein Profilbild, ersetzen deinen Namen in den Spielaufzeichnungen und Replays der anderen Spieler durch „Gelöschter Spieler“, behalten von dir gesendetes Feedback, entfernen aber deine E-Mail-Adresse und dein Konto daraus und löschen seine Kopie in unserem Discord-Feedback-Kanal, und wir kündigen ein laufendes Abonnement und löschen deinen Kundendatensatz bei Stripe. Von dir eingereichte Meldungen und Meldungen über dich verlieren ihre Verknüpfung mit deinem Konto; die Kopie gemeldeter Inhalte bleibt für die Aufbewahrungsdauer der Meldung erhalten. Wenn du dich nicht mehr anmelden kannst, schreib von der Adresse des Kontos an {{email}}, dann löschen wir es für dich.',
      forget: 'Gäste: „Vergiss mich“ im Gastmenü löscht deinen Gastdatensatz und deine Plätze in Spielen, ersetzt deinen Namen in den Aufzeichnungen der anderen Spieler durch „Gelöschter Spieler“ und entfernt die Gastdaten auf diesem Gerät. Wenn du in einem laufenden Spiel sitzt, beende oder verlasse es zuerst.',
      email: 'Alles andere, auch Daten, die der Download nicht enthält, richtest du an {{email}}. Wir antworten innerhalb eines Monats und können dich bitten zu bestätigen, dass das Konto dir gehört.',
      required: 'Um ein Konto zu erstellen, brauchst du eine E-Mail-Adresse und ein Passwort oder einen Anmeldeanbieter; als Gast kannst du ohne beides spielen. Wir treffen keine Entscheidungen über dich, die ausschließlich auf automatisierter Verarbeitung beruhen.',
    },
    complaints: {
      title: '8. Beschwerden',
      body: 'Du hast das Recht, dich bei Datatilsynet, der norwegischen Datenschutzbehörde, oder bei der Aufsichtsbehörde an deinem Wohn- oder Arbeitsort zu beschweren. Wir würden uns freuen, wenn du uns zuerst die Gelegenheit gibst, die Sache in Ordnung zu bringen: Schreib an {{email}}.',
    },
    security: {
      title: '9. Sicherheit',
      body: 'Passwörter werden nur als bcrypt-Hashes gespeichert, der gesamte Datenverkehr läuft über HTTPS, und nur die Dienste, die es brauchen, können auf die Datenbank zugreifen. Ein Zurücksetzen des Passworts meldet alle anderen Sitzungen ab, eine abgeschlossene E-Mail-Änderung meldet alle ab.',
    },
    children: {
      title: '10. Kinder',
      body: 'Boardly ist nicht für Kinder unter 13 Jahren bestimmt, und wir erheben wissentlich keine Daten von ihnen. Ein Konto beruht auf dem Vertrag, den du beim Erstellen akzeptierst (Art. 6 Abs. 1 lit. b DSGVO), nicht auf einer Einwilligung, daher gilt das Einwilligungsalter aus Art. 8 DSGVO und § 5 des Personendatengesetzes (personopplysningsloven) dafür nicht. Um ein Konto zu erstellen, musst du 13 Jahre oder älter sein: Du bestätigst das und akzeptierst die Nutzungsbedingungen im Registrierungsformular oder bei deinem ersten Besuch, wenn du dich mit Google, GitHub oder Discord registrierst, und wir speichern den Zeitpunkt, zu dem du das getan hast. Wenn du glaubst, dass ein Kind unter 13 Jahren uns personenbezogene Daten gegeben hat, schreib an {{email}}, und wir löschen sie.',
    },
